const domainMatches=(host,domain)=>host===domain||host.endsWith('.'+domain);
export function allowedEvidenceURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&(!u.port||u.port==='443')&&[...PRIMARY_DOMAINS,...SOURCES.filter(s=>s.enabled).map(s=>new URL(s.home).hostname)].some(d=>domainMatches(u.hostname,d));}catch{return false;}}
export function extractLinks(html,base){const links=[];for(const m of html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)){let url;try{url=safeURL(new URL(decode(m[1]),base).href);}catch{continue;}if(!url||/\.(jpg|jpeg|png|gif|webp|svg|zip|7z|rar|exe|csv|sql|db)(\?|$)/i.test(url)||url===base)continue;const label=clean(m[2]).slice(0,160);if(!label||/^(home|accueil|privacy|cookies|contact|login|subscribe|facebook|twitter|linkedin)$/i.test(label))continue;if(!links.some(l=>l.url===url))links.push({url,label,kind:PRIMARY_DOMAINS.some(d=>domainMatches(new URL(url).hostname,d))?'Référence institutionnelle ou technique candidate':'Lien cité · origine à vérifier'});}return links.slice(0,40);}
export function disclosureMentions(text,url){const names=[['BreachForums',/breachforums/i],['Telegram',/telegram/i],['Forum de divulgation',/hacking forum|forum de pirates|cybercrime forum/i],['Site de revendication de rançongiciel',/leak site|data leak site|site de revendication|site de fuite/i],['Dark web',/dark web|darknet/i],['GitHub',/github/i]];return names.flatMap(([name,re])=>{const m=re.exec(text);if(!m)return [];return [{platform:name,evidence:text.slice(Math.max(0,m.index-110),m.index+220),reportedBy:url,status:'Mention dans une publication ; emplacement non vérifié'}];});}
